import{z as p,x as E,o as r,c as B,q as n,j as d,D as t,d as s,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Dijkstra","description":"","frontmatter":{"title":"Dijkstra","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dijkstra.md","filePath":"cs/dijkstra.md","lastUpdated":1791063341000}'),u={name:"cs/dijkstra.md"};function A(h,a,m,D,c,k){const i=E("Mermaid");return r(),B("div",null,[a[2]||(a[2]=n('<h1 id="dijkstra" tabindex="-1">Dijkstra <a class="header-anchor" href="#dijkstra" aria-label="Permalink to &quot;Dijkstra&quot;">​</a></h1><div class="epigraph"><p>非负边权上，每次把估计最小的未确定顶点钉死；松弛不会再减小它。</p><footer>—— 据 Dijkstra, A Note on Two Problems in Connexion with Graphs, 1959；CLRS 第 24 章整理</footer></div><p>上一课<a href="/cs/topo-sort">拓扑排序</a>给了 DAG 上的线性序，但一般有向图可以有环，边还可以带<strong>非负</strong>权。BFS 只处理权为 \\(1\\)。本课不重做队列分层。缺口是：把「当前最近的未确定点」用<a href="/cs/heap-priority">优先队列</a>选出，并证明一旦取出，距离不再变。本课只处理单源、权 \\(\\ge 0\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(d[v]\\) 是当前从 \\(s\\) 到 \\(v\\) 的上界。松弛边 \\((u,v)\\)：若 \\(d[v]\\gt d[u]+w(u,v)\\) 则更新。BFS 的正确性依赖层数；权不等时层数不是路径权。缺口是集合 \\(S\\)：已取出的顶点。不变式：\\(u\\in S\\) 则 \\(d[u]=\\delta(s,u)\\)。每次从 \\(V\\setminus S\\) 取 \\(d\\) 最小者加入——非负权保证没有更短的路会从 \\(V\\setminus S\\) 绕回来把它改小。</p><p><span class="marginnote">「松弛」可译成「用中转站挑战旧记录」：手头只记着到 \\(v\\) 的当前最短估计 \\(d[v]\\)，每当路过 \\(u\\) 就试一次「\\(u\\) 再走一步到 \\(v\\) 会不会更短」。数字实例：\\(d[u]=3\\)、\\(w(u,v)=4\\)、\\(d[v]=10\\)，则 \\(3+4=7\\lt 10\\)，\\(d[v]\\) 被压到 7；若 \\(d[v]\\) 本来就是 6，则不动。</span></p><p>负权使这条论证失败：更短的路可以晚到。那是下一课 Bellman–Ford。本课也不做全源。</p><h3 id="二叉堆不是算法本身" tabindex="-1">二叉堆不是算法本身 <a class="header-anchor" href="#二叉堆不是算法本身" aria-label="Permalink to &quot;二叉堆不是算法本身&quot;">​</a></h3><p>算法是贪心取出加松弛。实现用二叉堆时 \\(O((V+E)\\log V)\\)；斐波那契堆 \\(O(E+V\\log V)\\)。邻接矩阵加扫描最小 \\(d\\) 是 \\(O(V^2)\\)。课程主干记二叉堆；不要把堆当成 Dijkstra 的定义。</p><p><span class="marginnote">Dijkstra 1959 原文同时谈最短路与最小生成树的一种过程。CLRS 把非负单源写成 Extract-Min 循环。贪心正确性的一般模板在后课，本课先把这条特例钉死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(d[s]=0\\)，其余 \\(\\infty\\)。\\(Q\\) 为优先队列。循环：取出 \\(u\\)，对每条出边松弛。终止 \\(Q\\) 空。不可达点保持 \\(\\infty\\)。</p>',12)),(r(),d(l,null,{default:t(()=>[o(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%BA%90%20s%22%5D%20--%3E%20Q%5B%22%E4%BC%98%E5%85%88%E9%98%9F%E5%88%97%E6%8C%89%20d%22%5D%0A%20%20Q%20--%3E%20U%5B%22%E5%8F%96%E5%87%BA%20d%20%E6%9C%80%E5%B0%8F%E7%9A%84%20u%22%5D%0A%20%20U%20--%3E%20REL%5B%22%E6%9D%BE%E5%BC%9B%E5%87%BA%E8%BE%B9%22%5D%0A%20%20REL%20--%3E%20Q%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"正确性：非负权 + 循环不变式。不要对负权实例「再跑一遍 Dijkstra」。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"前驱 \\(\\pi\\) 给出一条最短路树。与 BFS：权全 \\(1\\) 时 Extract-Min 的次序与队列一致，Dijkstra 退化成 BFS，但堆的对数因子仍在，实现上应换回队列。DAG 上按拓扑松弛是 \\(O(V+E)\\)，不必堆——那是拓扑课留下的用法，本课处理有环非负。",-1)),(r(),d(l,null,{default:t(()=>[o(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20SET%5B%22%E5%B7%B2%E5%8F%96%E5%87%BA%E9%9B%86%E5%90%88%20S%EF%BC%9Ad%20%E5%B7%B2%E6%98%AF%E6%9C%80%E7%BB%88%E5%80%BC%22%5D%0A%20%20%20%20U%5B%22u%EF%BC%9Ad%3D4%22%5D%0A%20%20end%0A%20%20subgraph%20REST%5B%22%E6%9C%AA%E5%8F%96%E5%87%BA%E7%82%B9%EF%BC%9Ad%20%E5%8F%AA%E6%98%AF%E4%B8%8A%E7%95%8C%22%5D%0A%20%20%20%20Y%5B%22y%EF%BC%9Ad%3D6%22%5D%0A%20%20%20%20X%5B%22x%EF%BC%9Ad%3D9%22%5D%0A%20%20end%0A%20%20U%20--%3E%7C%22w%3D2%22%7C%20Y%0A%20%20U%20--%3E%7C%22w%3D5%22%7C%20X%0A%20%20Y%20--%3E%7C%22w%3D2%22%7C%20X%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>这张图回答「为什么取出后 \\(d\\) 不再变」：\\(x\\) 的估计 9 仍会被「经 \\(y\\)」的 \\(6+2=8\\) 压小，但这类修正只发生在未取出点之间。一旦 \\(y\\) 以 6 被取出，任何从 \\(V\\setminus S\\) 绕回 \\(y\\) 的路都至少要先走过一个 \\(d\\ge 6\\) 的点，非负权使总长 \\(\\ge 6\\)——所以 6 就是终值。</p><p><span class="marginnote">直觉类比：把取出的点想成「已公布的成绩单」。公布后不再改，是因为剩下的选手每一步都不倒扣分（边权非负），追上已公布者的路只会更长。若允许负权（倒扣分），后来者完全可能绕一圈反超，成绩单就不能提前钉死——这正是负权图上 Dijkstra 失效的全部原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>负环、负边一律不保证。全源用后课 Floyd 或 \\(V\\) 次本算法（仍要非负）。启发式 \\(A^*\\) 是一致势函数下的同一骨架，本课不引入。点权可化成边权，不另开算法。</p><p>后课默认：非负单源 = Dijkstra；实现默认二叉堆。负权入口是 Bellman–Ford。</p><p><span class="marginnote">常见误区：初学者容易以为图里只有一两条负边时「跑一遍 Dijkstra 再局部修正」就行。实际上算法一旦用被污染的距离顺序取出了错误的点，它的 \\(d\\) 值会被当作最终答案参与后续松弛，错误会静默扩散到整棵最短路树——不存在只补几个点的修法，要么换算法，要么用 Johnson 势函数把边权整体抬成非负。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非负权下 Extract-Min 钉死最短距离。</li><li>二叉堆 \\(O((V+E)\\log V)\\)；权为 \\(1\\) 应退回 BFS。</li><li>负边使不变式失效。</li><li>出处：Dijkstra, 1959；CLRS 第 24.3 节。</li></ul>',8))])}const S=p(u,[["render",A]]);export{f as __pageData,S as default};
